<template><div v-if="client"><div class="page-head"><div><RouterLink to="/clients" class="text-[11px] font-bold text-indigo-600">← Clients</RouterLink><h1 class="mt-2">{{client.name}}</h1><p>{{client.client_number}} · {{client.phone||'No phone'}} · {{client.email||'No email'}}</p></div><div class="action-row"><RouterLink :to="`/clients/${client.id}/statement`" class="btn btn-soft">Statement</RouterLink><RouterLink to="/invoices" class="btn btn-soft">Invoices</RouterLink><RouterLink :to="`/payments?client_id=${client.id}`" class="btn btn-primary">Receive payment</RouterLink></div></div><div class="grid grid-cols-1 gap-3 sm:grid-cols-3"><div class="card metric"><div class="metric-label">Outstanding</div><div class="metric-value mt-2">{{money(client.outstanding)}}</div><div class="metric-trend mt-3">Current customer balance</div></div><div class="card metric"><div class="metric-label">Credit limit</div><div class="metric-value mt-2">{{money(client.credit_limit)}}</div><div class="metric-trend mt-3">Configured customer limit</div></div><div class="card metric"><div class="metric-label">Total sales</div><div class="metric-value mt-2">{{money(client.sales_total)}}</div><div class="metric-trend mt-3">Lifetime completed sales</div></div></div><div class="mt-4 grid grid-cols-1 gap-4 xl:grid-cols-2"><div class="card overflow-hidden"><div class="px-5 py-4"><h2 class="text-sm font-extrabold">Recent invoices</h2></div><table class="data-table"><thead><tr><th>Invoice</th><th>Total</th><th>Balance</th><th>Status</th></tr></thead><tbody><tr v-for="i in client.invoices||[]" :key="i.id"><td><RouterLink :to="`/invoices/${i.id}`" class="font-bold text-indigo-600">{{i.invoice_number}}</RouterLink></td><td>{{money(i.total)}}</td><td>{{money(i.balance)}}</td><td><StatusBadge :value="i.status"/></td></tr><tr v-if="!(client.invoices||[]).length"><td colspan="4"><div class="empty">No invoices for this client.</div></td></tr></tbody></table></div><div class="card overflow-hidden"><div class="px-5 py-4"><h2 class="text-sm font-extrabold">Recent payments</h2></div><table class="data-table"><thead><tr><th>Receipt</th><th>Date</th><th>Method</th><th>Amount</th></tr></thead><tbody><tr v-for="p in client.payments||[]" :key="p.id"><td><RouterLink :to="`/payments/${p.id}`" class="font-bold text-indigo-600">{{p.payment_number}}</RouterLink></td><td>{{formatDisplayDate(p.payment_date)}}</td><td class="capitalize">{{p.method}}</td><td>{{money(p.amount)}}</td></tr><tr v-if="!(client.payments||[]).length"><td colspan="4"><div class="empty">No payments recorded.</div></td></tr></tbody></table></div></div><div class="card mt-4 overflow-hidden"><div class="px-5 py-4"><h2 class="text-sm font-extrabold">Recent sales</h2></div><table class="data-table"><thead><tr><th>Sale</th><th>Date</th><th>Total</th><th>Payment</th></tr></thead><tbody><tr v-for="s in client.sales||[]" :key="s.id"><td><RouterLink :to="`/sales/${s.id}`" class="font-bold text-indigo-600">{{s.sale_number}}</RouterLink></td><td>{{formatDisplayDate(s.sale_date)}}</td><td>{{money(s.total)}}</td><td class="capitalize">{{s.payment_status}}</td></tr></tbody></table></div></div><div v-else class="empty">Loading client...</div></template>
<script setup lang="ts">import {formatDate as formatDisplayDate} from '../../utils/date';import {onMounted,ref} from 'vue';import {useRoute} from 'vue-router';import {api} from '../../services/api';import StatusBadge from '../../components/StatusBadge.vue';const route=useRoute(),client=ref<any>(null);function money(v:any){return new Intl.NumberFormat('en-TZ',{style:'currency',currency:'TZS',maximumFractionDigits:0}).format(Number(v||0))}onMounted(async()=>{const r=await api.get(`/clients/${route.params.id}`);client.value=r.data})</script>
